INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Funktionstest immer automatisiert?', 2, '[{"text": "Nein", "correct": true, "because": "Manuelle Tests möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend automatisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Funktionstest für einen Webserver?', 3, '[{"text": "Diensteverfügbarkeit prüfen", "correct": true, "because": "Sicherstellen, dass der Dienst läuft"}, {"text": "Maximale Last testen", "correct": false, "because": "Das ist Performancetest"}, {"text": "Schwachstellen finden", "correct": false, "because": "Sicherheitstest"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen einen Funktionstest für Konnektivität effektiv?', 5, '[{"text": "Ping-Tests", "correct": true, "because": "Überprüft Erreichbarkeit"}, {"text": "Port-Überprüfung", "correct": true, "because": "Dienste antworten"}, {"text": "Hohe Last", "correct": false, "because": "Performancetest"}, {"text": "Einfache Tools", "correct": false, "because": "Funktionalität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Funktionstests prüfen Diensteverfügbarkeit. b) Konnektivitätstests brauchen keine Tools.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Tools oft nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Funktionstest für einen Mailserver?', 4, '[{"text": "SMTP-Port", "correct": false, "because": "Kern der Funktion"}, {"text": "E-Mail-Versand", "correct": false, "because": "Hauptfunktion prüfen"}, {"text": "Grafikleistung", "correct": true, "because": "Irrelevant für Mail"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Funktionstest die Leistung misst?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Verfügbarkeit"}, {"text": "Ja", "correct": false, "because": "Das ist Performancetest"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature priorisiere ich bei einem Konnektivitätstest?', 3, '[{"text": "Erreichbarkeit", "correct": true, "because": "Sicherstellen, dass Verbindungen stehen"}, {"text": "Datenrate", "correct": false, "because": "Sekundär"}, {"text": "GUI-Tools", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Funktionstest?', 5, '[{"text": "Bestätigt Dienstelauf", "correct": true, "because": "Überprüft Verfügbarkeit"}, {"text": "Schnelle Fehlererkennung", "correct": true, "because": "Probleme früh finden"}, {"text": "Hohe Lastprüfung", "correct": false, "because": "Performancetest"}, {"text": "Kostensenkung", "correct": false, "because": "Nicht direkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Funktionstests prüfen grundlegende Funktionen. b) Konnektivitätstests messen Bandbreite. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Fokus auf Erreichbarkeit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Funktionstest eines Webservers?', 4, '[{"text": "HTTP-Zugriff", "correct": false, "because": "Kern der Funktion"}, {"text": "Port 80/443", "correct": false, "because": "Muss erreichbar sein"}, {"text": "Lasttests", "correct": true, "because": "Performancetest"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Prüfen Funktionstests Sicherheitslücken?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Funktionalität"}, {"text": "Ja", "correct": false, "because": "Das ist Sicherheitstest"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für einen Konnektivitätstest entscheidend?', 4, '[{"text": "Ping-Ergebnisse", "correct": true, "because": "Zeigt Erreichbarkeit"}, {"text": "Firewall-Regeln", "correct": true, "because": "Beeinflusst Verbindung"}, {"text": "CPU-Auslastung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Funktionstests Downtime verhindern. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Erkennung, keine Prävention"}, {"text": "Ja", "correct": false, "because": "Indirekt durch Fehlerfindung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Funktionstest für einen DNS-Server?', 3, '[{"text": "Namensauflösung", "correct": true, "because": "Kernfunktion prüfen"}, {"text": "Maximale Last", "correct": false, "because": "Performancetest"}, {"text": "GUI-Zugriff", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Konnektivitätstests prüfen Netzwerkverbindungen. b) Funktionstests messen Antwortzeiten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Antwortzeiten sind Performancetest"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein manueller Funktionstest?', 5, '[{"text": "Zeitaufwand", "correct": true, "because": "Langsamer als automatisiert"}, {"text": "Fehleranfälligkeit", "correct": true, "because": "Menschliche Fehler möglich"}, {"text": "Hohe Genauigkeit", "correct": false, "because": "Nicht garantiert"}, {"text": "Geringer Aufwand", "correct": false, "because": "Mehr Arbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Konnektivitätstest für VMs unwichtig?', 3, '[{"text": "Netzwerkadapter", "correct": false, "because": "Verbindung nötig"}, {"text": "IP-Erreichbarkeit", "correct": false, "because": "Kern der Prüfung"}, {"text": "Lokale Speichergeschwindigkeit", "correct": true, "because": "Netzwerkfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Testen Funktionstests die Benutzerfreundlichkeit?', 3, '[{"text": "Nein", "correct": true, "because": "Fokus auf technische Funktion"}, {"text": "Ja", "correct": false, "because": "Das ist Usability-Test"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Funktionstest Sicherheitsaspekte prüft?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Verfügbarkeit und Funktion"}, {"text": "Ja", "correct": false, "because": "Sicherheitstest separat"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Test wähle ich für einen Datenbankserver?', 4, '[{"text": "Funktionstest", "correct": true, "because": "Prüft Abfragen und Erreichbarkeit"}, {"text": "Performancetest", "correct": false, "because": "Fokus auf Last"}, {"text": "Sicherheitstest", "correct": false, "because": "Schwachstellen separat"}]');
